#include "projectile/visualizer.hpp"
#include <opencv2/imgproc.hpp>
#include <string>
namespace projectile { cv::Mat Visualizer::draw(const cv::Mat& f,const std::vector<Track>& ts,const TrailStore& trails,const std::unordered_map<int,ArcResult>& arcs,std::uint64_t n,bool warm)const{cv::Mat o=f.clone();for(auto&t:ts){cv::rectangle(o,{t.box.x,t.box.y,t.box.width,t.box.height},{0,255,0},1);cv::circle(o,t.center,2,{255,0,0},-1);cv::putText(o,"ID "+std::to_string(t.id)+(t.predicted?" PRED":""),{t.box.x,t.box.y-4},cv::FONT_HERSHEY_SIMPLEX,.45,{0,0,255},1);if(auto tr=trails.get(t.id))for(size_t i=1;i<tr->size();++i)cv::line(o,(*tr)[i-1].point,(*tr)[i].point,{0,255,255},1);}for(auto&[id,a]:arcs){if(a.valid){cv::polylines(o,a.arc,false,{92,230,92},2);cv::polylines(o,a.extrapolation,false,{44,44,255},2);}}cv::putText(o,"Frame: "+std::to_string(n)+" Tracks: "+std::to_string(ts.size())+(warm?"":"  MOG2 warming"),{10,24},cv::FONT_HERSHEY_SIMPLEX,.55,{255,255,255},1);return o;} }
